import type { InlineBadgeProps } from "./inline-badge.types";

import { forwardRef } from "react";
import { clsx } from "clsx";
import { useTheme } from "@theme";

import { InlineBadgeClasses, StyledInlineBadge } from "./inline-badge.styles";

const InlineBadge = forwardRef(
  (
    { className, variant = "default", size = "default", children, ...props }: InlineBadgeProps,
    ref: React.ForwardedRef<HTMLDivElement>,
  ) => {
    const theme = useTheme(),
      rootClasses = clsx(InlineBadgeClasses.root, className, {
        [InlineBadgeClasses.sm]: size === "sm",
      });

    return (
      <StyledInlineBadge
        ref={ref}
        className={rootClasses}
        currentTheme={theme}
        size={size}
        variant={variant}
        {...props}
      >
        {children}
      </StyledInlineBadge>
    );
  },
);

InlineBadge.displayName = "InlineBadge";

export default InlineBadge;
